import { test, expect } from '@playwright/test';

test.use({ storageState: '../auth/user.json' });

test.describe('2. Бизнес-профиль — встроенная карта', () => {
  test('2.3 Нажатие на карту открывает варианты навигации @desktop @prod-safe (#6a7c8dc36076099644cfa2b8)', async ({ page }) => {
    // 1. Guard сессии как в 2.2; открыть `/u/MM9548`, дождаться карты.
    await page.goto('/');
    test.skip(/\/(welcome|sign-in)/.test(page.url()), 'Сессия user не авторизована: npm run qa-login:manual -- user');
    await page.goto('/u/MM9548');
    const map = page.locator('img[src^="data:image/png"]').first();
    await expect(map).toBeVisible();

    // 2. Нажать на карту.
    await map.click();

    // Варианты навигации
    await expect(page.getByText('Waze')).toBeVisible();
    await expect(page.getByText('Google Maps')).toBeVisible();
    await expect(page.getByText(/Show on map|הצגה במפה/i)).toBeVisible();
    await expect(page.getByText(/Copy address|העתקת הכתובת/i)).toBeVisible();

    // 3. Ничего не выбирать, закрыть меню (Escape).
    await page.keyboard.press('Escape');
  });
});
